TriggerOraclev10g.body:
BEGIN
    IF :new.data_predare < :new.data_ridicare THEN
        RAISE_APPLICATION_ERROR(-20003, 
            'Eroare: Data predare (' || TO_CHAR(:new.data_predare, 'DD.MM.YYYY') || 
            ') nu poate fi inainte de data ridicarii (' || TO_CHAR(:new.data_ridicare, 'DD.MM.YYYY') || ').');
    END IF;
END;
